author: naren-ambati · merged by: naren-ambati
title: Clear the cached subtotal on remove
description:
The subtotal cache was cleared by add() but not by remove(), so a removed line kept being charged. Clear it in remove() too, with a test.

--- src/cart.js (modified, +1 −0)
@@ -19,6 +19,7 @@ export class Cart {

   remove(sku) {
     this.#lines.delete(sku);
+    this.#subtotal = null;
     return this;
   }


--- test/cart.test.js (modified, +7 −0)
@@ -41,3 +41,10 @@ test("cartFromJSON does not run code in its input", () => {
   assert.throws(() => cartFromJSON('{"lines": []} && (globalThis.pwned = true)'), SyntaxError);
   assert.equal(globalThis.pwned, undefined);
 });
+
+test("removing a line updates a cached subtotal", () => {
+  const c = new Cart().add("apple", 1).add("pear", 2);
+  assert.equal(c.subtotalCents(), 300);
+  c.remove("pear");
+  assert.equal(c.subtotalCents(), 100);
+});

